corrected_code:
const { get, param, HttpErrors } = require('@loopback/rest');
const { repository } = require('@loopback/repository');
const { authenticate } = require('@loopback/authentication');
const { inject } = require('@loopback/core');
const { SecurityBindings } = require('@loopback/security');

class ShipmentController {
  constructor(
    @repository('ShipmentRepository') private shipmentRepository,
    @inject(SecurityBindings.USER) private currentUser
  ) {}

  @get('/api/v1/shipments/{id}')
  @authenticate('jwt')
  async getShipmentDetails(@param.path.string('id') id: string) {
    const shipment = await this.shipmentRepository.findById(id);
    if (!shipment) {
      throw new HttpErrors.NotFound('Shipment not found');
    }

    // Verify shipment belongs to the authenticated shipper organization
    if (shipment.shipperId !== this.currentUser.shipperId) {
      throw new HttpErrors.Forbidden('Access denied: shipment belongs to another shipper');
    }

    return {
      id: shipment.id,
      trackingNumber: shipment.trackingNumber,
      cargoManifest: shipment.cargoManifest,
      coordinates: shipment.currentGpsLocation,
      destination: shipment.destinationPort
    };
  }
}
